/* Isolated design prototype. No requests, persistence, or operational calculations. */
const $ = (s) => document.querySelector(s);
const esc = (s) => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => '₹' + Number(n).toLocaleString('en-IN');
const initialPeople = () => [{name:'Lakshmi R',phone:'9000000001',initials:'LR'},{name:'Kumar S',phone:'9000000002',initials:'KS'},{name:'Meena P',phone:'9000000003',initials:'MP'}];
let people, state, photoUrl, toastTimer;
function reset() { if(photoUrl) URL.revokeObjectURL(photoUrl); photoUrl=null; people=initialPeople(); state={view:'counter',step:0,borrower:null,items:[{description:'Gold chain',weight:'8.50',purity:'22K'}],principal:10000,status:'new',paid:0}; render(); }
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
const button=(label,action,kind='primary',extra='')=>`<button class="button ${kind}" data-action="${action}" ${extra}>${label}</button>`;
function heading(title,sub){return `<div class="heading"><div><span class="eyebrow">AMUDHA JEWELLERS · COUNTER</span><h1>${title}</h1><p>${sub}</p></div><span class="quiet-label">Sample session</span></div>`;}
function summary(){return `<aside class="summary"><div class="card"><div class="summary-label">${['active','released'].includes(state.status)?'PRINCIPAL REMAINING':'PROPOSED LOAN'}</div><div class="summary-amount">${money(state.principal-state.paid)}</div><div class="summary-caption">Illustrative amounts only</div><hr><div class="summary-line"><span>Borrower</span><strong>${state.borrower?esc(state.borrower.name):'Choose a borrower'}</strong></div><div class="summary-line"><span>Collateral</span><strong>${state.items.length} gold item${state.items.length>1?'s':''}</strong></div><div class="summary-line"><span>Monthly interest</span><strong>2% · sample terms</strong></div><div class="summary-line"><span>Tenure</span><strong>3 months</strong></div><div class="summary-bottom">This concept demonstrates the workflow. The application will supply validated terms, eligibility, dues, and evidence.</div></div><div class="help-note"><b>ⓘ</b><span>One clear next action, with the loan summary always close at hand.</span></div></aside>`;}
function steps(){return `<ol class="steps">${['Borrower','Collateral','Terms & review','Complete'].map((label,i)=>`<li><button class="step ${i===state.step?'current':i<state.step?'done':''}" data-step="${i}" ${i>=state.step||state.status!=='new'?'disabled':''} ${i===state.step?'aria-current="step"':''}><b>${i<state.step?'✓':i+1}</b>${label}</button></li>`).join('')}</ol>`;}
function borrowerRows(query=''){const rows=people.filter(p=>(p.name+' '+p.phone).toLowerCase().includes(query.toLowerCase()));return rows.length?rows.map(p=>`<button class="borrower-option ${state.borrower===p?'selected':''}" data-person="${people.indexOf(p)}" aria-pressed="${state.borrower===p}"><span class="avatar">${esc(p.initials)}</span><span class="meta"><strong>${esc(p.name)}</strong><small>${esc(p.phone)} · Sample borrower</small></span><span class="badge neutral">Party record</span><span class="radio-circle" aria-hidden="true">✓</span></button>`).join(''):'<div class="empty">No borrowers found. Add a sample borrower to continue.</div>';}
function borrower(){return `<section class="card"><div class="card-header"><div><h2>Who are you serving?</h2><p>Find a borrower or create their Party record.</p></div><button class="text-button" data-action="add-borrower">+ Add borrower</button></div><label for="search">Search by name or mobile number</label><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" type="search" placeholder="Try Lakshmi or 9000000001" autocomplete="off"></div><div class="list-heading">Sample borrowers</div><div id="borrower-results">${borrowerRows()}</div><div class="borrower-footer"><span class="check-circle">✓</span>Borrower records stay within this Workspace.</div></section><div class="actionbar"><span class="actionbar-note">Step 1 of 4 · Start with the borrower</span><div class="action-buttons">${button('Continue to collateral →','collateral','primary',state.borrower?'':'disabled')}</div></div>`;}
function collateral(){return `<form id="collateral-form"><section class="card"><div class="card-header"><div><h2>Record the pledged items</h2><p>Keep the description clear for identification at release.</p></div></div>${state.items.map((item,i)=>`<div class="collateral-item"><div class="item-title"><h3><span class="item-number">${String(i+1).padStart(2,'0')}</span>Gold item</h3>${state.items.length>1?`<button type="button" class="text-button" data-remove="${i}">Remove item ${i+1}</button>`:''}</div><div class="form-grid"><div class="wide"><label for="description-${i}">Item description</label><input id="description-${i}" data-field="description" data-index="${i}" value="${esc(item.description)}" required maxlength="100"></div><div><label for="weight-${i}">Net weight (g)</label><input id="weight-${i}" data-field="weight" data-index="${i}" type="number" min="0.01" max="10000" step="0.01" value="${esc(item.weight)}" required></div><div><label for="purity-${i}">Purity</label><select id="purity-${i}" data-field="purity" data-index="${i}">${['22K','20K','18K'].map(p=>`<option ${item.purity===p?'selected':''}>${p}</option>`).join('')}</select></div></div></div>`).join('')}<button class="text-button" type="button" data-action="add-item">+ Add another item</button><div class="upload-box"><div class="upload-title"><strong>Reference photo</strong><span class="muted">Optional in this concept</span></div><button class="button secondary" type="button" data-camera-open>Take photo</button><label for="photo" style="margin-top:12px">Or upload an image</label><input id="photo" type="file" accept="image/*"><div id="photo-preview">${photoUrl?`<img src="${photoUrl}" alt="Selected collateral reference">`:''}</div><p class="field-hint">Take a photo with your camera or choose an existing image. It stays in this demo session.</p></div></section><div class="actionbar"><span class="actionbar-note">Step 2 of 4 · Identify each item</span><div class="action-buttons">${button('Back','back','secondary','type="button"')}<button type="submit" class="button primary">Review terms →</button></div></div></form>`;}
function review(){return `<form id="review-form"><section class="card"><div class="card-header"><h2>Agree the loan details</h2><span class="badge amber">Not saved</span></div><div class="review-borrower"><span class="avatar">${esc(state.borrower.initials)}</span><div><strong>${esc(state.borrower.name)}</strong><small>${esc(state.borrower.phone)}</small></div></div><label for="principal">Loan amount (₹)</label><input class="money-input" id="principal" type="number" min="100" max="1000000" step="1" value="${state.principal}" required><dl class="review-list"><div><dt>Monthly interest</dt><dd>2% · sample terms</dd></div><div><dt>Loan tenure</dt><dd>3 months</dd></div><div><dt>Collateral</dt><dd>${state.items.map(i=>`${esc(i.description)} · ${esc(i.weight)} g · ${esc(i.purity)}`).join('<br>')}</dd></div><div><dt>Disbursal method</dt><dd>Cash · sample</dd></div></dl><details><summary>What happens after saving?</summary><p>A draft is reviewed and approved before disbursal. Operational eligibility, valuation, permissions, and calculations remain enforced by the application.</p></details><div class="notice warning">These are illustrative terms, not a lending quote. Saving creates a draft in this browser session only.</div></section><div class="actionbar"><span class="actionbar-note">Step 3 of 4 · Review before approval</span><div class="action-buttons">${button('Back','back','secondary','type="button"')}<button class="button primary" type="submit">Save sample draft →</button></div></div></form>`;}
function complete(){const approved=state.status==='approved';return `<section class="card"><div class="success-mark">✓</div><div class="card-header"><div><h2>${approved?'Approved. Ready to disburse.':'Draft ready for approval'}</h2><p>Sample loan LN-DEMO-001 · ${esc(state.borrower.name)}</p></div><span class="badge ${approved?'':'amber'}">${approved?'Approved':'Draft'}</span></div><div class="receipt-block"><div class="muted">${approved?'Cash to hand to the borrower':'Proposed principal'}</div><div class="big">${money(state.principal)}</div></div><p class="muted">${approved?'Confirm the cash handoff separately. This demonstrates disbursal without moving money.':'Approval and disbursal are separate actions. Check the terms and collateral before approving.'}</p><label class="check-label"><input id="confirm-action" type="checkbox">${approved?'Simulate confirmation that the borrower received the cash.':'I have reviewed the sample borrower, collateral, and terms.'}</label><div class="actionbar"><span class="actionbar-note">Step 4 of 4 · ${approved?'Disbursal':'Approval'}</span>${button(approved?'Confirm sample disbursal':'Approve sample loan',approved?'disburse':'approve','primary','disabled')}</div></section>`;}
function servicing(){const released=state.status==='released',remaining=state.principal-state.paid;return heading(released?'Collateral handed back':'Serve an existing loan',released?'The sample loan journey is complete.':'Collect a repayment or settle and release the pledged items.')+`<div class="content-grid"><section class="card"><div class="card-header"><div><h2>${esc(state.borrower.name)}</h2><p>LN-DEMO-001 · ${esc(state.borrower.phone)}</p></div><span class="badge">${released?'Released':remaining?'Active':'Paid · awaiting handoff'}</span></div>${released?`<div class="success-mark">✓</div><p>The sample balance is settled and the item handoff is recorded in this session.</p>${button('Start another sample loan','new')}`:remaining?`<div class="notice">Same-day sample: interest and fees are ₹0. Real settlement dues come from the application.</div><form id="repayment-form"><label for="repayment">Cash repayment amount (₹)</label><input id="repayment" class="money-input" type="number" min="1" max="${remaining}" step="1" value="${Math.min(1000,remaining)}" required><p class="field-hint">Remaining principal: ${money(remaining)}</p><label class="check-label"><input type="checkbox" required>Simulate confirmation that the cash was received.</label><div class="actionbar"><button class="text-button" type="button" data-action="pay-full">Use full balance</button><button class="button primary" type="submit">Record sample repayment</button></div></form>`:`<div class="receipt-block"><div class="muted">Sample balance due</div><div class="big">₹0</div></div><h2>Return the pledged items</h2><p>${state.items.map(i=>`${esc(i.description)} · ${esc(i.weight)} g`).join('<br>')}</p><label class="check-label"><input id="confirm-action" type="checkbox">Simulate confirming the borrower received all listed items.</label><div class="actionbar">${button('Confirm sample handoff','release','primary','disabled')}</div>`}<details style="margin-top:24px"><summary>Loan activity & evidence</summary><ul class="timeline"><li>Draft reviewed and approved<small>Sample session · Rajesh</small></li><li>Cash disbursal · ${money(state.principal)}<small>Sample confirmation only</small></li>${state.paid?`<li>Repayments collected · ${money(state.paid)}<small>Illustrative total in this session</small></li>`:''}${released?'<li>Collateral handoff confirmed<small>Sample session complete</small></li>':''}</ul><p>Official receipts, immutable document issues, and reprints remain in the live application. This prototype generates no documents.</p></details></section>${summary()}</div>`;}
function secondary(){const v=state.view;if(v==='loans')return heading('Loans','Pick up where the counter left off.')+`<section class="card"><div class="card-header"><h2>Current sample session</h2>${button('Return to counter →','counter')}</div>${state.status==='new'?'<div class="empty">No saved sample loan yet. Start at the counter to create one.</div>':`<div class="table-wrap"><table><thead><tr><th>Loan / borrower</th><th>Principal</th><th>Status</th><th>Next action</th></tr></thead><tbody><tr><td><strong>LN-DEMO-001</strong>${esc(state.borrower.name)}</td><td>${money(state.principal-state.paid)}</td><td><span class="badge">${esc(state.status)}</span></td><td>${button('Open loan','counter','secondary')}</td></tr></tbody></table></div>`}</section>`;
if(v==='parties')return heading('Parties','Borrower records, close to the lending workflow.')+`<section class="card"><div class="card-header"><h2>Sample borrowers</h2>${button('Add borrower','add-borrower')}</div><p class="muted">Select a borrower to start an unsaved counter journey. Reset the demo to begin again after saving a loan.</p>${borrowerRows()}</section>`;
if(v==='rates')return heading('Rates','A consistent home for reference information.')+`<section class="card"><h2>Rate reference preview</h2><div class="notice warning">No live market data is connected. Valuation and rate management need a separate design review.</div><p class="muted">The counter journey uses sample terms of 2% monthly interest over 3 months. These are loan terms, not commodity prices.</p>${button('Return to counter','counter','secondary')}</section>`;
if(v==='notify')return heading('Notify','Keep borrower communication understandable.')+`<section class="card"><h2>No messages in this sample session</h2><div class="empty">Notification configuration and delivery history will follow the reviewed shared layout.</div><div class="notice">Nothing is sent from this prototype.</div>${button('Return to counter','counter','secondary')}</section>`;
return heading('Workspace setup','See the prerequisites before serving your first borrower.')+`<section class="card"><h2>Sample Workspace readiness</h2>${[['Workspace identity','Amudha Jewellers · Anna Nagar'],['Counter access','Sample owner role'],['Lending configuration','Illustrative terms and cash method'],['Document setup','Official evidence stays in the application']].map(([a,b])=>`<div class="setup-row"><span class="check-circle">✓</span><span><strong>${a}</strong><small>${b}</small></span><span class="badge neutral">Illustrative</span></div>`).join('')}<div class="notice warning">This is a readiness layout preview, not a check of your real Workspace configuration.</div>${button('Go to the counter →','counter')}</section>`;}
function render(focus=false){$('#section-label').textContent=state.view==='setup'?'Workspace setup':state.view[0].toUpperCase()+state.view.slice(1);document.querySelectorAll('[data-view]').forEach(el=>{const active=el.dataset.view===state.view;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});$('#screen').innerHTML=state.view!=='counter'?secondary():['active','released'].includes(state.status)?servicing():heading('New loan','A clear path from borrower to cash in hand.')+steps()+`<div class="content-grid"><div>${[borrower,collateral,review,complete][state.step]()}</div>${summary()}</div>`;if(focus)$('#main').focus();}
function navigate(view){state.view=view;$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render(true);}
document.addEventListener('click',e=>{const el=e.target.closest('button,a.brand');if(!el)return;if(el.matches('a.brand')){e.preventDefault();navigate('counter');}if(el.dataset.view)navigate(el.dataset.view);if(el.hasAttribute('data-close'))el.closest('dialog').close();if(el.dataset.person!==undefined){if(state.status!=='new'){toast('Reset the demo to start a loan for another borrower.');return;}state.borrower=people[Number(el.dataset.person)];if(state.view==='parties')navigate('counter');else{const query=$('#search')?.value||'';$('#borrower-results').innerHTML=borrowerRows(query);$('[data-action="collateral"]').disabled=false;$('[data-person="'+el.dataset.person+'"]').focus();const aside=$('.summary');aside.outerHTML=summary();}}if(el.dataset.step!==undefined){state.step=Number(el.dataset.step);render(true);}if(el.dataset.remove!==undefined){state.items.splice(Number(el.dataset.remove),1);render(true);}switch(el.dataset.action){case 'add-borrower':if(state.status!=='new'){toast('Reset the demo before adding another borrower.');break;}$('#borrower-dialog').showModal();break;case 'counter':navigate('counter');break;case 'collateral':if(state.borrower){state.step=1;render(true);}break;case 'back':state.step--;render(true);break;case 'add-item':state.items.push({description:'',weight:'',purity:'22K'});render();$(`#description-${state.items.length-1}`).focus();break;case 'approve':if($('#confirm-action').checked){state.status='approved';render(true);}break;case 'disburse':if($('#confirm-action').checked){state.status='active';render(true);toast('Sample disbursal recorded. No money moved.');}break;case 'pay-full':$('#repayment').value=state.principal-state.paid;$('#repayment').focus();break;case 'release':if($('#confirm-action').checked){state.status='released';render(true);toast('Sample handoff complete.');}break;case 'new':reset();break;}});
document.addEventListener('input',e=>{if(e.target.id==='search')$('#borrower-results').innerHTML=borrowerRows(e.target.value);if(e.target.dataset.field)state.items[Number(e.target.dataset.index)][e.target.dataset.field]=e.target.value;if(e.target.id==='principal'&&e.target.checkValidity()){state.principal=Number(e.target.value);$('.summary').outerHTML=summary();}});
document.addEventListener('change',e=>{if(e.target.id==='confirm-action')$('[data-action="approve"],[data-action="disburse"],[data-action="release"]').disabled=!e.target.checked;if(e.target.id==='photo'){const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file for the local preview.');e.target.value='';return;}if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(file);$('#photo-preview').innerHTML=`<img src="${photoUrl}" alt="Selected collateral reference">`;}});
document.addEventListener('submit',e=>{e.preventDefault();if(!e.target.reportValidity())return;switch(e.target.id){case 'borrower-form':{const name=$('#borrower-name').value.trim();if(!name){$('#borrower-name').setCustomValidity('Enter a borrower name.');$('#borrower-name').reportValidity();return;}const p={name,phone:$('#borrower-phone').value,initials:name.split(/\s+/).map(s=>s[0]).slice(0,2).join('').toUpperCase()};people.push(p);state.borrower=p;$('#borrower-dialog').close();e.target.reset();navigate('counter');toast('Sample borrower selected.');break;}case 'collateral-form':state.step=2;render(true);break;case 'review-form':state.principal=Number($('#principal').value);state.status='draft';state.step=3;render(true);break;case 'repayment-form':state.paid+=Number($('#repayment').value);render(true);toast('Sample repayment recorded.');break;}});
$('#borrower-name').addEventListener('input',e=>e.target.setCustomValidity(''));
$('#reset').addEventListener('click',()=>{reset();toast('Demo reset. All sample changes cleared.');});
$('#workspace-picker').addEventListener('click',()=>$('#workspace-dialog').showModal());
$('#menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
reset();
